ALTER TABLE `organizations` ADD COLUMN `contact_person` VARCHAR(100) DEFAULT NULL AFTER `type`;

CREATE TABLE IF NOT EXISTS `news` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `content` text NOT NULL,
  `icon_name` varchar(50) DEFAULT 'newspaper',
  `thumbnail_url` text DEFAULT NULL,
  `published_at` timestamp NULL DEFAULT current_timestamp(),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ALTER TABLE `news` ADD COLUMN `thumbnail_url` text DEFAULT NULL;
ALTER TABLE `news` ADD COLUMN `published_at` timestamp NULL DEFAULT current_timestamp();

CREATE TABLE IF NOT EXISTS `pricing_settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `setting_key` varchar(50) NOT NULL UNIQUE,
  `setting_value` decimal(10,2) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ON DUPLICATE KEY UPDATE `setting_value` = VALUES(`setting_value`);

